import re
from dataclasses import dataclass
from typing import List, Optional, Tuple

# ----------------------------------------------------------------------
#  Semantic version parsing and comparison
# ----------------------------------------------------------------------
@dataclass(frozen=True)
class Version:
    major: int
    minor: int
    patch: int
    prerelease: Tuple[str, ...]  # empty tuple if none

    @staticmethod
    def _split_identifiers(s: str, allow_leading_zero: bool) -> Tuple[Tuple[str, ...], bool]:
        """Split an identifier string into parts and validate."""
        parts = s.split('.')
        if not parts:
            return tuple(), False
        for part in parts:
            if not part:
                return tuple(), False
            if not re.fullmatch(r'[0-9A-Za-z-]+', part):
                return tuple(), False
            if part.isdigit():
                if not allow_leading_zero and part != '0' and part.startswith('0'):
                    return tuple(), False
        return tuple(parts), True

    @classmethod
    def from_string(cls, s: str) -> Optional["Version"]:
        """Parse a version string according to the spec. Return None if invalid."""
        # Split build metadata
        if '+' in s:
            main, _build = s.split('+', 1)
            # Build metadata is ignored for precedence, but must be valid
            if not re.fullmatch(r'[0-9A-Za-z-]+(?:\.[0-9A-Za-z-]+)*', _build):
                return None
        else:
            main = s

        # Split pre-release
        if '-' in main:
            core, pre = main.split('-', 1)
            pre_parts, ok = cls._split_identifiers(pre, allow_leading_zero=True)
            if not ok:
                return None
        else:
            core = main
            pre_parts = tuple()

        # Parse core
        core_parts = core.split('.')
        if len(core_parts) != 3:
            return None
        try:
            major, minor, patch = (int(p) for p in core_parts)
        except ValueError:
            return None
        # Validate no leading zeros
        for p in core_parts:
            if len(p) > 1 and p.startswith('0'):
                return None
        return cls(major, minor, patch, pre_parts)

    def __lt__(self, other: "Version") -> bool:
        if self.major != other.major:
            return self.major < other.major
        if self.minor != other.minor:
            return self.minor < other.minor
        if self.patch != other.patch:
            return self.patch < other.patch
        # Now prerelease comparison
        if not self.prerelease and other.prerelease:
            return False  # self is greater
        if self.prerelease and not other.prerelease:
            return True
        if not self.prerelease and not other.prerelease:
            return False  # equal
        # Both have prerelease
        for a, b in zip(self.prerelease, other.prerelease):
            a_isnum = a.isdigit()
            b_isnum = b.isdigit()
            if a_isnum and b_isnum:
                a_int = int(a)
                b_int = int(b)
                if a_int != b_int:
                    return a_int < b_int
            elif a_isnum and not b_isnum:
                return True
            elif not a_isnum and b_isnum:
                return False
            else:
                if a != b:
                    return a < b  # ASCII order
        # All shared identifiers equal
        return len(self.prerelease) < len(other.prerelease)

    def __eq__(self, other: object) -> bool:
        if not isinstance(other, Version):
            return False
        return (
            self.major == other.major
            and self.minor == other.minor
            and self.patch == other.patch
            and self.prerelease == other.prerelease
        )

# ----------------------------------------------------------------------
#  Comparator parsing and matching
# ----------------------------------------------------------------------
@dataclass
class Comparator:
    operator: Optional[str]   # None means implicit range for partial/wildcard
    pattern_type: str         # 'full', 'partial', 'wildcard'
    full_version: Optional[Version] = None   # for full pattern
    numbers_written: Tuple[int, ...] = ()    # for partial patterns
    has_pre_release: bool = False           # if full pattern has pre-release
    pre_release_major_min: Optional[Tuple[int, int, int]] = None  # for pre-release rule

    def matches(self, v: Version) -> bool:
        # Handle wildcard (matches only non-pre-release)
        if self.pattern_type == 'wildcard':
            return v.prerelease == ()

        # Handle full version comparators
        if self.pattern_type == 'full':
            if self.operator in ('<', '<=', '>', '>='):
                if self.operator == '<':
                    return v < self.full_version
                if self.operator == '<=':
                    return v <= self.full_version
                if self.operator == '>':
                    return v > self.full_version
                if self.operator == '>=':
                    return v >= self.full_version
            elif self.operator in ('=', None):
                return v == self.full_version
            elif self.operator in ('^', '~'):
                # Lower bound inclusive
                if v < self.full_version:
                    return False
                # Upper bound exclusive
                upper = self._upper_bound_for_full(self.full_version)
                return v < upper
            else:
                # Should not happen
                return False

        # Handle partial patterns (range)
        lower = self._lower_bound_for_partial()
        if v < lower:
            return False
        upper = self._upper_bound_for_partial()
        if upper is not None and v >= upper:
            return False
        return True

    def _lower_bound_for_partial(self) -> Version:
        nums = list(self.numbers_written)
        # pad to 3 with zeros
        while len(nums) < 3:
            nums.append(0)
        return Version(nums[0], nums[1], nums[2], tuple())

    def _upper_bound_for_partial(self) -> Optional[Version]:
        # If wildcard_everything, no upper bound
        if self.pattern_type == 'wildcard':
            return None
        # Compute upper by incrementing last specified numeric part
        nums = list(self.numbers_written)
        if not nums:
            return None  # wildcard_everything handled earlier
        idx = len(nums) - 1
        nums[idx] += 1
        # Pad to 3
        while len(nums) < 3:
            nums.append(0)
        return Version(nums[0], nums[1], nums[2], ('0',))  # prerelease -0

    def _upper_bound_for_full(self, ver: Version) -> Version:
        # For ^ and ~ operators on full versions
        # Compute upper bound per spec
        nums = [ver.major, ver.minor, ver.patch]
        # Determine left-most non-zero among numbers written
        idx = None
        for i, n in enumerate(nums):
            if n != 0:
                idx = i
                break
        if idx is None:
            idx = 2  # all zero, last written number
        nums[idx] += 1
        for j in range(idx + 1, 3):
            nums[j] = 0
        return Version(nums[0], nums[1], nums[2], ('0',))

# ----------------------------------------------------------------------
#  Alternative and parsing
# ----------------------------------------------------------------------
@dataclass
class Alternative:
    comparators: List[Comparator]
    prerelease_major_min: List[Tuple[int, int, int]]  # list of (major,minor,patch) from full pre-release comparators

def parse_range_expr(expr: str) -> List[Alternative]:
    if not expr.strip():
        raise ValueError("Empty range")
    # Split by '||'
    parts = re.split(r'\s*\|\|\s*', expr.strip())
    alternatives: List[Alternative] = []
    for alt_str in parts:
        alt_str = alt_str.strip()
        if not alt_str:
            raise ValueError("Empty alternative")
        # Split by whitespace
        comps_raw = re.split(r'\s+', alt_str)
        comparators: List[Comparator] = []
        prerelease_majminpatch: List[Tuple[int, int, int]] = []
        for comp_str in comps_raw:
            if not comp_str:
                continue
            # Determine operator
            op = None
            rest = comp_str
            if rest.startswith(('<=', '>=')):
                op = rest[:2]
                rest = rest[2:]
            elif rest[0] in ('<', '>', '=','^','~'):
                op = rest[0]
                rest = rest[1:]
            else:
                op = None  # implicit
            if not rest:
                raise ValueError(f"Missing pattern in comparator '{comp_str}'")
            # No space allowed between operator and pattern; already split
            # Validate operator not used with pattern without number
            if op and not any(c.isdigit() for c in rest):
                raise ValueError(f"Operator '{op}' used with pattern lacking number in '{comp_str}'")
            # Validate pattern
            if '*' in rest or 'x' in rest or 'X' in rest:
                # wildcard pattern
                if op is not None:
                    raise ValueError(f"Operator with wildcard in '{comp_str}'")
                # Ensure pattern is only wildcards possibly separated by dots
                parts_pat = rest.split('.')
                if any(p not in ('*','x','X') for p in parts_pat):
                    raise ValueError(f"Invalid wildcard pattern '{rest}'")
                comparator = Comparator(operator=None, pattern_type='wildcard')
                comparators.append(comparator)
                continue
            # Pattern without wildcard
            # Check for build metadata
            if '+' in rest:
                raise ValueError(f"Build metadata not allowed in pattern '{rest}'")
            # Determine if full version or partial
            if '-' in rest:
                # Must be full version with pre-release
                full = Version.from_string(rest)
                if not full:
                    raise ValueError(f"Invalid full version pattern '{rest}'")
                comparator = Comparator(
                    operator=op if op else '=',  # no operator treated as '='
                    pattern_type='full',
                    full_version=full,
                    has_pre_release=bool(full.prerelease),
                )
                if comparator.has_pre_release:
                    prerelease_majminpatch.append((full.major, full.minor, full.patch))
                comparators.append(comparator)
                continue
            # No pre-release
            # Parse as partial or full
            parts_pat = rest.split('.')
            # Validate each part
            numbers = []
            for part in parts_pat:
                if not part:
                    raise ValueError(f"Invalid pattern part in '{rest}'")
                if part in ('*','x','X'):
                    # wildcard part, must be last
                    if part != parts_pat[-1]:
                        raise ValueError(f"Wildcard must be last in '{rest}'")
                    # After wildcard only wildcards allowed
                    if any(p not in ('*','x','X') for p in parts_pat[parts_pat.index(part):]):
                        raise ValueError(f"Wildcard followed by non-wildcard in '{rest}'")
                    break
                if not part.isdigit():
                    raise ValueError(f"Non-numeric part in pattern '{rest}'")
                if len(part) > 1 and part.startswith('0'):
                    raise ValueError(f"Leading zeros not allowed in '{rest}'")
                numbers.append(int(part))
            if len(numbers) == 3 and len(parts_pat) == 3:
                # full version without pre-release
                full = Version(numbers[0], numbers[1], numbers[2], tuple())
                comparator = Comparator(
                    operator=op if op else '=',  # no operator treated as '='
                    pattern_type='full',
                    full_version=full,
                    has_pre_release=False,
                )
                comparators.append(comparator)
            else:
                # partial pattern
                comparator = Comparator(
                    operator=op,
                    pattern_type='partial',
                    numbers_written=tuple(numbers),
                )
                comparators.append(comparator)
        alternatives.append(Alternative(comparators, prerelease_majminpatch))
    return alternatives

# ----------------------------------------------------------------------
#  Main function
# ----------------------------------------------------------------------
def best_match(versions: List[str], range_expr: str) -> Optional[str]:
    if not versions:
        raise ValueError("No versions provided")

    # Parse valid versions
    parsed_versions: List[Tuple[Version, str]] = []
    for v_str in versions:
        v = Version.from_string(v_str)
        if v is not None:
            parsed_versions.append((v, v_str))

    if not parsed_versions:
        raise ValueError("No valid versions")

    # Parse range expression
    alternatives = parse_range_expr(range_expr)

    # Helper to test if a version satisfies the range
    def satisfies(v: Version) -> bool:
        for alt in alternatives:
            ok = True
            for comp in alt.comparators:
                if not comp.matches(v):
                    ok = False
                    break
            if ok:
                # pre-release rule
                if v.prerelease:
                    # if any comparator in this alternative is a full pre-release with same major.minor.patch
                    found = False
                    for m in alt.prerelease_major_min:
                        if (v.major, v.minor, v.patch) == m:
                            found = True
                            break
                    if not found:
                        ok = False
                # else non pre-release passes
            if ok:
                return True
        return False

    best_version: Optional[Tuple[Version, str]] = None
    for v, orig in parsed_versions:
        if satisfies(v):
            if best_version is None or v > best_version[0]:
                best_version = (v, orig)
            # tie: keep earlier one (current loop order preserves original order)
    return best_version[1] if best_version else None
